import app from 'flarum/admin/app';
import Switch from 'flarum/common/components/Switch';
import { AdminComponent, getBool, saveSetting } from '../util';

// Self-contained boolean toggle: updates app.data.settings + persists immediately.
export default class AdminToggle extends AdminComponent {
  view() {
    const {
      settingKey,
      label,
      help
    } = this.attrs;
    const value = getBool(settingKey);
    return m("div", {
      className: "Form-group AvocadoAdmin-toggle"
    }, m(Switch, {
      state: value,
      onchange: checked => {
        app.data.settings[settingKey] = checked;
        m.redraw();
        saveSetting({
          [settingKey]: checked ? '1' : '0'
        });
      }
    }, label), help && m("p", {
      className: "helpText"
    }, help));
  }
}
flarum.reg.add('ramon-avocado', 'admin/components/AdminToggle', AdminToggle);